SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.drug_type, COUNT(DISTINCT CASE WHEN e.charttime BETWEEN a.intime AND a.intime + INTERVAL '48 hours' THEN e.emar_id END)::FLOAT / NULLIF(COUNT(DISTINCT CASE WHEN e.charttime BETWEEN a.intime + INTERVAL '12 hours' AND a.outtime THEN e.emar_id END), 0) AS proportion, COUNT(DISTINCT CASE WHEN e.charttime BETWEEN a.intime AND a.intime + INTERVAL '48 hours' THEN e.emar_id END) - COUNT(DISTINCT CASE WHEN e.charttime BETWEEN a.intime + INTERVAL '12 hours' AND a.outtime THEN e.emar_id END) AS difference FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN emar e ON a.subject_id = e.subject_id JOIN prescriptions d ON e.emar_id = d.pharmacy_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 36 AND 46 AND d.drug_type IN ('antidiabetic', 'cardiac') AND EXISTS (SELECT 1 FROM diagnoses_icd WHERE subject_id = p.subject_id AND icd_code IN ('440', '448')) GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.drug_type;